"""Read-only native export projection: actual hours, dated filters, privacy and lifecycle."""
import copy,csv,io,json,unittest
import evolution as engine
from archives import created,action
from change_sets import apply

def fixture(start='2027-05-03',end='2027-05-05'):
 s=engine.upgraded(start=start,end=end);s['policies']=[];s['constraints']=[];s['baseConstraintIds']=[]
 for profile in s['weekProfiles']:profile['offWeekdays']=[]
 s['shifts'][0]['id']='normal'
 s['shifts'][0]['intervals']=[dict(start='09:00',end='12:00',endDayOffset=0),dict(start='14:00',end='18:00',endDayOffset=0)]
 s['allowedShifts']=[dict(id='force-'+e['id'],selector={'employeeIds':[e['id']]},scope={},shiftIds=[['normal','closing','off'][i]]) for i,e in enumerate(s['employees'])]
 return s

def options(a):return dict(start=a['period']['start'],end=a['period']['end'],employeeSelection=dict(all=True,employeeIds=[],typeIds=[],groupIds=[]),shiftSelection=dict(mode='ALL',shiftIds=[],normalShiftIds=['normal'],hideNormal=False),showAbsences=True,showRest=True,showClosuresAndHolidays=True,includeAbsenceReasons=False)
def view(s,a,o=None):return action(s,[a],'VIEW',id=a['id'],options=o or options(a))
class CalendarExports(unittest.TestCase):
 def test_actual_split_and_dated_variant(self):
  s=fixture();s['shifts'][0]['variants']=[dict(id='base',label='Base',priority=0,selector={},scope={},intervals=s['shifts'][0]['intervals']),dict(id='wed',label='Wednesday',priority=1,selector={},scope={'weekdays':[3]},intervals=[dict(start='10:00',end='13:00',endDayOffset=0)])]
  a=created(s);v=view(s,a)['document'];cells=[c for c in v['cells'] if c['employeeId']=='e1'];self.assertEqual(len(cells[0]['intervals']),2);self.assertEqual(cells[2]['intervals'][0]['start'],'10:00');self.assertIn('startUtcMinute',cells[0]['intervals'][0]);self.assertEqual(cells[0]['state'],'WORKING');self.assertEqual(v['format'],'rostercore.calendar-view');self.assertFalse(v['authoritative'])
 def test_filters_do_not_modify_original_or_turn_hidden_work_into_rest(self):
  s=fixture();a=created(s);before=json.dumps(a,sort_keys=True);o=options(a);o['shiftSelection']['hideNormal']=True;v=view(s,a,o)['document'];self.assertEqual({c['state'] for c in v['cells']},{'FILTERED_SHIFT','WORKING','REST'});self.assertTrue(all(c['intervals']==[] for c in v['cells'] if c['state']=='FILTERED_SHIFT'));self.assertEqual(json.dumps(a,sort_keys=True),before);self.assertEqual(action(s,[a],'BACKUP',createdAt='2026-11-09T12:00:00Z')['document']['archives'][0],a)
 def test_rest_toggle_independent_of_working_selection(self):
  s=fixture();a=created(s);o=options(a);o['shiftSelection']['mode']='MANUAL';o['shiftSelection']['shiftIds']=['closing'];self.assertIn('REST',{c['state'] for c in view(s,a,o)['document']['cells']});o['showRest']=False;self.assertIn('FILTERED_REST',{c['state'] for c in view(s,a,o)['document']['cells']})
 def test_inclusive_source_bounded_period_and_unknown_ids(self):
  s=fixture();a=created(s);o=options(a);o['start']=o['end']='2027-05-04';v=view(s,a,o)['document'];self.assertEqual(len(v['days']),1);self.assertEqual(len(v['cells']),3);o['end']='2027-05-06';self.assertEqual(view(s,a,o)['diagnostics'][0]['code'],'EXPORT_PERIOD');o=options(a);o['employeeSelection']['employeeIds']=['unknown'];self.assertEqual(view(s,a,o)['diagnostics'][0]['code'],'REFERENCE')
 def test_explicit_normal_definition(self):
  s=fixture();a=created(s);o=options(a);o['shiftSelection'].update(normalShiftIds=[],hideNormal=True);self.assertEqual(view(s,a,o)['diagnostics'][0]['code'],'EXPORT_NORMAL');o['shiftSelection']['normalShiftIds']=['off'];self.assertEqual(view(s,a,o)['diagnostics'][0]['code'],'EXPORT_NORMAL')
 def test_person_role_and_group_selection_uses_dated_native_membership(self):
  s=fixture();s['attributeDefinitions']=[dict(id='contract',label='Contract',type='ENUM',values=['full','part'],default='full')];s['employeeTypes'].append(dict(id='new-role',label='New role'));s['employees'][0]['versions']=[dict(validFrom='2027-05-04',typeId='new-role',attributes={'contract':'part'})];s['groups']=[dict(id='part',label='Part',selector={'where':dict(op='EQ',attributeId='contract',value='part')})];a=created(s);o=options(a);o['employeeSelection']=dict(all=False,employeeIds=[],typeIds=[],groupIds=['part']);v=view(s,a,o)['document'];self.assertEqual([e['id'] for e in v['employees']],['e1']);self.assertEqual([c['state'] for c in v['cells']],['FILTERED_PERSON','WORKING','WORKING']);o['employeeSelection']['employeeIds']=['e2'];self.assertEqual(len(view(s,a,o)['document']['employees']),2);o['employeeSelection']=dict(all=False,employeeIds=[],typeIds=[s['employees'][0]['typeId']],groupIds=[]);self.assertEqual(len(view(s,a,o)['document']['employees']),3);self.assertEqual(sum(c['state']=='FILTERED_PERSON' for c in view(s,a,o)['document']['cells']),2)
 def test_absence_rest_inactive_excluded_and_closure_remain_distinct(self):
  s=fixture(end='2027-05-07');s['employees'][1]['employment']={'validFrom':'2027-05-04'};s['availability']=[dict(id='absence',selector={'employeeIds':['e1']},scope={'start':'2027-05-03','end':'2027-05-03'},state='ABSENT')];s['calendar']['excludedDates']=['2027-05-04'];s['calendar']['closures']=[dict(id='closed',label='Closed',validFrom='2027-05-05',validTo='2027-05-06',selector={},reason='Shutdown',exceptions=[])];a=created(s);v=view(s,a)['document'];self.assertTrue({'ABSENT','EXCLUDED','INACTIVE','REST','CLOSED','WORKING'}<={c['state'] for c in v['cells']});self.assertNotIn('absenceReasons',next(c for c in v['cells'] if c['state']=='ABSENT'));o=options(a);o.update(showAbsences=False,showClosuresAndHolidays=False);v=view(s,a,o)['document'];self.assertTrue({'FILTERED_ABSENCE','FILTERED_CLOSED'}<={c['state'] for c in v['cells']})
 def test_privacy_reasons_are_existing_and_opt_in(self):
  s=fixture();s['availability']=[dict(id='absence',selector={'employeeIds':['e1']},scope={'start':'2027-05-03','end':'2027-05-03'},state='ABSENT')];s['hrState']['events']=[dict(eventId='leave-1',source='hr',revision=1,externalId='leave',employeeId='e1',operation='UPSERT',start='2027-05-03',end='2027-05-03',status='APPROVED',absenceType='Private leave')];a=created(s);self.assertNotIn('Private leave',json.dumps(view(s,a)['document']));o=options(a);o['includeAbsenceReasons']=True;v=view(s,a,o)['document'];self.assertEqual(next(c for c in v['cells'] if c['state']=='ABSENT')['absenceReasons'],['Private leave'])
 def test_dst_and_unsupported_timezone_no_guessed_offset(self):
  s=fixture('2026-10-25','2026-10-25');s['calendar']['timezone']='Europe/Rome';s['shifts'][0]['intervals']=[dict(start='01:30',end='03:30',endDayOffset=0)];a=created(s);c=next(c for c in view(s,a)['document']['cells'] if c['employeeId']=='e1');i=c['intervals'][0];self.assertEqual(i['endUtcMinute']-i['startUtcMinute'],180);s['calendar']['timezone']='America/New_York';a=created(s);i=next(c for c in view(s,a)['document']['cells'] if c['employeeId']=='e1')['intervals'][0];self.assertNotIn('startUtcMinute',i);self.assertEqual(i['timeError']['code'],'UNSUPPORTED_TIMEZONE')
 def test_fold_and_overnight_uid_stability(self):
  s=fixture('2026-10-25','2026-10-25');s['calendar']['timezone']='Europe/Rome';s['shifts'][0]['intervals']=[dict(start='02:15',end='02:45',endDayOffset=0,startFold=0,endFold=1)];a=created(s);v=view(s,a)['document'];i=next(c for c in v['cells'] if c['employeeId']=='e1')['intervals'][0];self.assertEqual(i['endUtcMinute']-i['startUtcMinute'],90);b=created(s,'different-archive');self.assertEqual(v['cells'][0]['intervals'][0]['uid'],view(s,b)['document']['cells'][0]['intervals'][0]['uid'])
 def test_lifecycle_completed_prefix_and_publication_date(self):
  s=fixture();a=created(s);pub=action(s,[a],'PUBLISH',id=a['id']);done=action(pub['scenario'],pub['archives'],'COMPLETE',id=a['id'],through='2027-05-03');v=view(s,done['archives'][0])['document'];self.assertTrue(v['futurePublished']);self.assertEqual({c['lifecycle'] for c in v['cells'] if c['date']=='2027-05-03'},{'COMPLETED'});self.assertEqual({c['lifecycle'] for c in v['cells'] if c['date']=='2027-05-04'},{'PUBLISHED'});self.assertIn('publishedAt',v);draftdone=action(s,[a],'COMPLETE',id=a['id'],through='2027-05-03');self.assertFalse(view(s,draftdone['archives'][0])['document']['futurePublished'])
 def test_filtered_csv_protects_formulas_and_full_json_only_recovery(self):
  s=fixture();s['employees'][0]['label']='  =HYPERLINK("bad")';a=created(s);o=options(a);o['employeeSelection']=dict(all=False,employeeIds=['e1'],typeIds=[],groupIds=[]);r=action(s,[a],'CSV',id=a['id'],options=o);rows=list(csv.reader(io.StringIO(r['csv'])));self.assertEqual(len(rows),4);self.assertTrue(rows[1][1].startswith("'  ="));self.assertIn('09:00-12:00 | 14:00-18:00',rows[1]);out=action(s,[],'IMPORT',archive=r['document'],mode='REFERENCE');self.assertEqual(out['status'],'VALIDATION_ERROR');self.assertNotIn('scenario',out)
 def test_future_hours_preserve_completed_concrete_intervals(self):
  s=fixture();a=created(s);done=action(s,[a],'COMPLETE',id=a['id'],through='2027-05-03');current=done['scenario'];shift=copy.deepcopy(s['shifts'][0]);shift['variants']=[dict(id='normal',label='Existing',priority=0,selector={},scope={},intervals=shift['intervals']),dict(id='future',label='Future',priority=1,selector={},scope={'start':'2027-05-05'},intervals=[dict(start='10:00',end='19:00',endDayOffset=0)])];hashes=engine.call('context',current)['context']['entityHashes'];doc=dict(format='rostercore.scenario-change-set',schemaVersion=1,id='hours',scenarioId=s['id'],expectedRevision=current['revision'],allowHardRuleChanges=True,operations=[dict(op='REPLACE_SHIFT',value=shift,expectedEntityHash=hashes['shifts']['normal'])]);out=apply(current,doc);self.assertEqual(out['status'],'IMPORTED',out);self.assertEqual(out['scenario']['history'],current['history']);shift['variants'][0]['intervals'][0]['start']='08:00';doc['operations'][0]['value']=shift;self.assertEqual(apply(current,doc)['diagnostics'][0]['code'],'PROTECTED_ASSIGNMENT')
 def test_regeneration_preserves_original_number_encoding(self):
  s=fixture();s['search']['maxTimeSeconds']=20.0;a=created(s);readable=json.loads(a['scenarioEncoding']);readable['search']['maxTimeSeconds']=20;out=engine.call('regenerate',s,{'from':s['calendar']['start'],'previousScenario':readable,'previousScenarioEncoding':a['scenarioEncoding'],'previousResult':a['result'],'stabilityPriority':'AFTER_FAIRNESS'});self.assertIn(out['status'],['OPTIMAL','FEASIBLE'],out)
if __name__=='__main__':unittest.main(verbosity=2)
